import { useState, useEffect, useRef } from "react";

/* ═══════════════════════════════════════════════════════
   HISTORIA — v20 · 7 périodes + mode Expert (Cinéma)
   Logique métier : v5 (11) conservée intégralement
   Nouveau design : typographie éditoriale, palette crème/bleu
   Nouvelle intro : filtres libres période ET/OU thématique
═══════════════════════════════════════════════════════ */

const STYLES = `
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;0,900;1,400;1,700&family=IBM+Plex+Mono:wght@400;500&family=Barlow+Condensed:wght@400;500;600;700&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:     #F0EDE6;
  --ink:    #1A1A1A;
  --blue:   #1400FF;
  --muted:  #7A7874;
  --border: #C8C4BC;
  --surf:   #EAE7E0;
  --note:   #E4E1DA;
  --serif:  'Playfair Display', Georgia, serif;
  --mono:   'IBM Plex Mono', monospace;
  --cond:   'Barlow Condensed', sans-serif;
}

html, body, #root {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--cond);
  min-height: 100%;
}

/* ── LAYOUT ── */
.hz-wrap {
  min-height: 100vh;
  background: var(--bg);
  display: flex;
  flex-direction: column;
}
.hz-inner {
  width: 100%;
  max-width: 860px;
  margin: 0 auto;
  flex: 1;
  display: flex;
  flex-direction: column;
}

/* ── TOPBAR ── */
.hz-topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  border-bottom: 0.5px solid var(--border);
  font-family: var(--cond);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--muted);
}
.hz-topbar-left { display: flex; align-items: center; gap: 5px; }
.hz-logo-word { font-weight: 700; color: var(--ink); letter-spacing: 0.01em; }
.hz-dot { color: var(--blue); font-size: 16px; line-height: 1; }
.hz-sep { color: var(--border); margin: 0 1px; }

/* ── MAIN CONTENT AREA ── */
.hz-content { flex: 1; display: flex; flex-direction: column; }

/* ── FOOTER ── */
.hz-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 0.5px solid var(--border);
}

/* ── BUTTONS ── */
.btn-blue {
  display: flex;
  align-items: center;
  gap: 10px;
  background: none;
  border: none;
  cursor: pointer;
  font-family: var(--cond);
  font-size: 14px;
  font-weight: 600;
  color: var(--ink);
  letter-spacing: 0.02em;
}
.btn-blue:disabled { opacity: 0.3; cursor: not-allowed; }
.btn-arrow {
  width: 36px; height: 36px;
  background: var(--blue);
  color: white;
  border: none;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px;
  flex-shrink: 0;
  transition: opacity 0.15s;
  font-family: var(--cond);
}
.btn-arrow:hover:not(:disabled) { opacity: 0.85; }
.btn-arrow:disabled { opacity: 0.3; cursor: not-allowed; }
.btn-ghost {
  background: none;
  border: 0.5px solid var(--border);
  padding: 9px 18px;
  font-family: var(--cond);
  font-size: 13px;
  font-weight: 500;
  color: var(--muted);
  cursor: pointer;
  letter-spacing: 0.02em;
  transition: border-color 0.15s, color 0.15s;
}
.btn-ghost:hover { border-color: var(--ink); color: var(--ink); }
.btn-text-under {
  background: none; border: none; cursor: pointer;
  font-family: var(--cond); font-size: 13px; font-weight: 600;
  color: var(--ink); border-bottom: 1.5px solid var(--ink);
  padding-bottom: 1px; line-height: 1; transition: opacity 0.15s;
}
.btn-text-under:hover { opacity: 0.6; }
.btn-text-muted {
  background: none; border: none; cursor: pointer;
  font-family: var(--cond); font-size: 13px; font-weight: 500;
  color: var(--muted); border-bottom: 1.5px solid var(--border);
  padding-bottom: 1px; line-height: 1; transition: opacity 0.15s;
}
.btn-text-muted:hover { opacity: 0.6; }

/* ── ANIMATIONS ── */
@keyframes fadeUp { from{opacity:0;transform:translateY(16px)} to{opacity:1;transform:none} }
@keyframes fadeIn { from{opacity:0} to{opacity:1} }
.anim-up { animation: fadeUp 0.4s cubic-bezier(.22,.68,0,1.1) both; }
.anim-in { animation: fadeIn 0.35s ease both; }

/* ══════════════════════════════════════════════════
   ÉCRAN 1 — ACCUEIL
══════════════════════════════════════════════════ */
.accueil-body {
  display: flex;
  flex: 1;
  padding: 28px 20px 0;
  gap: 32px;
}
.accueil-left { flex: 1; }
.hz-big-logo {
  font-family: var(--serif);
  font-size: clamp(54px, 10vw, 80px);
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.02em;
  color: var(--ink);
  margin-bottom: 22px;
}
.hz-big-logo em { color: var(--blue); font-style: italic; }
.hz-tagline {
  font-family: var(--serif);
  font-style: italic;
  font-size: 15px;
  line-height: 1.6;
  color: var(--ink);
  max-width: 290px;
}
.accueil-right {
  width: 210px;
  border-left: 0.5px solid var(--border);
  padding-left: 20px;
  flex-shrink: 0;
}
.index-title {
  font-family: var(--cond);
  font-size: 10px; font-weight: 600;
  letter-spacing: 0.12em; color: var(--muted);
  margin-bottom: 10px;
}
.epoch-row {
  display: flex; justify-content: space-between; align-items: baseline;
  padding: 8px 0; border-top: 0.5px solid var(--border);
  cursor: default;
}
.epoch-num { font-family: var(--mono); font-size: 10px; color: var(--muted); margin-right: 7px; }
.epoch-name { font-family: var(--cond); font-weight: 600; font-size: 13px; color: var(--ink); }
.epoch-dates { font-family: var(--mono); font-size: 10px; color: var(--muted); }
.footer-stats { display: flex; gap: 22px; align-items: baseline; }
.stat-item { display: flex; flex-direction: column; align-items: flex-start; }
.stat-big { font-family: var(--serif); font-size: 30px; font-weight: 900; color: var(--blue); line-height: 1; }
.stat-label { font-family: var(--cond); font-size: 10px; font-weight: 600; letter-spacing: 0.1em; color: var(--muted); margin-top: 2px; }

/* ══════════════════════════════════════════════════
   ÉCRANS INTRO (joueurs, noms, filtres)
══════════════════════════════════════════════════ */
.intro-body {
  flex: 1;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
}
.intro-title {
  font-family: var(--serif);
  font-size: 32px;
  font-weight: 900;
  color: var(--ink);
  margin-bottom: 4px;
}
.intro-title em { color: var(--blue); font-style: italic; }
.intro-sub {
  font-family: var(--serif);
  font-style: italic;
  font-size: 14px;
  color: var(--muted);
  margin-bottom: 24px;
}
.intro-divider {
  height: 0.5px;
  background: var(--border);
  margin: 0 0 24px;
}

/* NB JOUEURS */
.nb-grid {
  display: flex;
  gap: 12px;
  margin-bottom: 8px;
}
.nb-btn {
  flex: 1;
  height: 80px;
  background: var(--surf);
  border: 0.5px solid var(--border);
  font-family: var(--serif);
  font-size: 34px;
  font-weight: 900;
  color: var(--muted);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: all 0.15s;
}
.nb-btn:hover { border-color: var(--ink); color: var(--ink); }
.nb-btn.sel { background: var(--blue); border-color: var(--blue); color: white; }
.nb-btn-label { font-family: var(--cond); font-size: 10px; font-weight: 600; letter-spacing: 0.1em; }

/* NOMS */
.noms-list { display: flex; flex-direction: column; gap: 10px; margin-bottom: 8px; }
.nom-row { display: flex; align-items: center; gap: 12px; }
.nom-avatar {
  width: 38px; height: 38px;
  border: 2px solid;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--serif); font-size: 15px; font-weight: 700;
  flex-shrink: 0; background: var(--surf);
}
.nom-input {
  flex: 1;
  background: var(--surf);
  border: 0.5px solid var(--border);
  padding: 11px 14px;
  font-family: var(--serif);
  font-size: 17px;
  color: var(--ink);
  outline: none;
  transition: border-color 0.15s;
  border-radius: 0;
  -webkit-appearance: none;
}
.nom-input:focus { border-color: var(--blue); }
.nom-input::placeholder { color: var(--muted); font-style: italic; }

/* FILTRES LIBRES */
.filtres-body { flex: 1; display: flex; flex-direction: column; }
.filtres-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 16px; }
.filtre-col {}
.filtre-col-title {
  font-family: var(--cond);
  font-size: 10px; font-weight: 600; letter-spacing: 0.12em;
  color: var(--muted); margin-bottom: 10px;
  display: flex; align-items: center; gap: 8px;
}
.filtre-col-title span {
  flex: 1; height: 0.5px; background: var(--border);
}
.filtre-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  cursor: pointer;
  border: 0.5px solid transparent;
  border-bottom: 0.5px solid var(--border);
  background: transparent;
  text-align: left;
  width: 100%;
  transition: all 0.12s;
}
.filtre-item:hover { background: var(--surf); }
.filtre-item.sel {
  background: var(--blue);
  border-color: var(--blue);
  color: white;
}
.filtre-item.sel .fi-label { color: white; }
.filtre-item.sel .fi-sub { color: rgba(255,255,255,0.65); }
.filtre-item.sel .fi-check { border-color: white; background: white; }
.filtre-item.sel .fi-check::after { opacity: 1; }
.fi-icon { font-size: 16px; flex-shrink: 0; }
.fi-label { font-family: var(--cond); font-size: 13px; font-weight: 600; color: var(--ink); }
.fi-sub { font-family: var(--mono); font-size: 10px; color: var(--muted); }
.fi-check {
  width: 16px; height: 16px; border: 1.5px solid var(--border);
  margin-left: auto; flex-shrink: 0; position: relative;
  transition: all 0.12s;
}
.fi-check::after {
  content: '';
  position: absolute;
  left: 3px; top: 0px;
  width: 5px; height: 9px;
  border: 2px solid var(--blue);
  border-left: none; border-top: none;
  transform: rotate(45deg);
  opacity: 0;
}
.filtre-hint {
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 16px;
  padding: 8px 0;
  border-top: 0.5px solid var(--border);
}
.filtre-recap {
  display: flex; gap: 8px; flex-wrap: wrap; align-items: center;
  padding: 10px 0;
  border-top: 0.5px solid var(--border);
  font-family: var(--cond); font-size: 11px; color: var(--muted);
  margin-bottom: 4px;
}
.recap-tag {
  background: var(--surf);
  border: 0.5px solid var(--border);
  padding: 3px 10px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink);
}
.recap-tag.blue {
  background: var(--blue);
  border-color: var(--blue);
  color: white;
}

/* ══════════════════════════════════════════════════
   ÉCRAN JEU
══════════════════════════════════════════════════ */
.info-bar {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  padding: 9px 20px;
  border-bottom: 0.5px solid var(--border);
}
.info-cell { display: flex; flex-direction: column; gap: 2px; }
.info-cell:nth-child(2) { align-items: center; text-align: center; }
.info-cell:nth-child(3) { align-items: flex-end; }
.info-label { font-family: var(--cond); font-size: 9px; font-weight: 600; letter-spacing: 0.12em; color: var(--muted); }
.info-val { font-family: var(--cond); font-size: 15px; font-weight: 700; color: var(--ink); }
.info-val-sm { font-family: var(--cond); font-size: 12px; font-weight: 600; color: var(--ink); line-height: 1.3; }
.player-dot { display: inline-block; width: 7px; height: 7px; margin-right: 5px; vertical-align: middle; }

.quiz-main {
  display: flex;
  padding: 14px 20px;
  gap: 20px;
  align-items: flex-start;
  border-bottom: 0.5px solid var(--border);
}
.date-block { flex: 1; }
.date-year {
  font-family: var(--serif); font-size: clamp(48px,8vw,64px);
  font-weight: 900; color: var(--blue); font-style: italic;
  line-height: 1; letter-spacing: -0.02em;
}
.date-era { font-family: var(--cond); font-size: 13px; color: var(--ink); font-weight: 500; margin-top: 2px; }
.date-place { font-family: var(--cond); font-size: 11px; color: var(--muted); margin-top: 3px; }
.timer-block { min-width: 120px; text-align: right; }
.timer-label { font-family: var(--cond); font-size: 10px; font-weight: 600; letter-spacing: 0.1em; color: var(--muted); margin-bottom: 3px; }
.timer-num { font-family: var(--serif); font-size: 48px; font-weight: 900; color: var(--ink); line-height: 1; }
.timer-num.urgent { color: #CC1100; }
.timer-s { font-size: 24px; font-weight: 400; color: var(--muted); font-family: var(--cond); }
.timer-bar-wrap { margin-top: 5px; height: 2px; background: var(--border); }
.timer-bar { height: 2px; background: var(--blue); transition: width 1s linear; }
.timer-bar.urgent { background: #CC1100; }

.question-block { padding: 14px 20px 10px; }
.question-text {
  font-family: var(--serif);
  font-size: clamp(18px, 2.8vw, 22px);
  font-weight: 700; line-height: 1.35; color: var(--ink);
}
.question-text em { color: var(--blue); font-style: italic; font-weight: 400; }

/* RÉPONSES */
.answers-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  margin: 0 20px;
  border: 0.5px solid var(--border);
}
.answer-cell {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 14px; cursor: pointer;
  border: 0.5px solid var(--border);
  background: transparent;
  font-family: var(--cond); font-size: 13px; font-weight: 500;
  color: var(--ink); text-align: left; position: relative;
  transition: background 0.12s;
}
.answer-cell:hover:not(.disabled) { background: var(--surf); }
.answer-cell.correct {
  background: var(--blue) !important;
  color: white !important;
  border-color: var(--blue) !important;
}
.answer-cell.correct .ans-letter { color: rgba(255,255,255,0.55); }
.answer-cell.wrong { background: var(--surf) !important; color: var(--muted) !important; }
.answer-cell.wrong .ans-text { text-decoration: line-through; }
.answer-cell.disabled { cursor: default; }
.ans-letter { font-family: var(--mono); font-size: 10px; color: var(--muted); min-width: 16px; flex-shrink: 0; }
.ans-dot { position: absolute; right: 10px; top: 50%; transform: translateY(-50%); width: 6px; height: 6px; background: white; border-radius: 50%; }

/* NOTE / SAVIEZ-VOUS */
.note-card {
  margin: 10px 20px;
  padding: 12px 14px;
  background: var(--note);
  border-top: 2px solid var(--blue);
}
.note-inner { display: flex; gap: 14px; }
.note-left { min-width: 75px; }
.note-tag { font-family: var(--cond); font-size: 10px; font-weight: 600; letter-spacing: 0.1em; color: var(--ink); }
.note-ref { font-family: var(--mono); font-size: 9px; color: var(--muted); margin-top: 2px; }
.note-text { font-family: var(--serif); font-size: 12px; line-height: 1.6; color: var(--ink); }
.note-text strong { color: var(--blue); font-style: normal; font-weight: 700; }
.note-text em { font-style: italic; }

/* SCORES FOOTER */
.scores-row { display: flex; gap: 14px; align-items: baseline; flex-wrap: wrap; }
.score-item { font-family: var(--cond); font-size: 11px; color: var(--muted); display: flex; align-items: baseline; gap: 3px; }
.score-val { font-family: var(--serif); font-size: 18px; font-weight: 900; color: var(--ink); }
.next-action { display: flex; align-items: center; gap: 10px; }
.next-label { font-family: var(--cond); font-size: 13px; font-weight: 600; color: var(--ink); }
.next-btn-wrap { opacity: 0.3; pointer-events: none; transition: opacity 0.2s; }
.next-btn-wrap.ready { opacity: 1; pointer-events: auto; }

/* TEMPS ÉCOULÉ */
.temps-ecoule {
  margin: 8px 20px 0;
  padding: 8px 14px;
  background: rgba(20, 0, 255, 0.06);
  border-left: 2px solid var(--blue);
  font-family: var(--serif); font-size: 13px; font-style: italic; color: var(--ink);
}

/* ══════════════════════════════════════════════════
   ÉCRAN RÉSULTATS
══════════════════════════════════════════════════ */
.res-subbar {
  display: flex; justify-content: space-between; align-items: center;
  padding: 8px 20px; border-bottom: 0.5px solid var(--border);
  font-family: var(--cond); font-size: 11px; color: var(--muted);
}
.res-subbar strong { color: var(--ink); font-weight: 600; }
.res-header {
  display: flex; align-items: flex-end;
  padding: 20px 20px 14px; gap: 28px;
  border-bottom: 0.5px solid var(--border);
  flex-wrap: wrap;
}
.fin-de { font-family: var(--serif); font-size: clamp(36px,6vw,52px); font-weight: 900; line-height: 1; color: var(--ink); }
.fin-session { font-family: var(--serif); font-size: clamp(36px,6vw,52px); font-weight: 900; font-style: italic; color: var(--blue); line-height: 1; }
.fin-bloc { line-height: 1.05; }
.global-stats { display: flex; gap: 24px; align-items: flex-end; padding-bottom: 2px; }
.gstat-val { font-family: var(--serif); font-size: 34px; font-weight: 900; color: var(--blue); font-style: italic; line-height: 1; }
.gstat-val.dark { color: var(--ink); font-style: normal; }
.gstat-unit { font-family: var(--cond); font-size: 14px; color: var(--muted); font-weight: 500; }
.gstat-label { font-family: var(--cond); font-size: 9px; font-weight: 600; letter-spacing: 0.1em; color: var(--muted); margin-top: 3px; }
.leaderboard { flex: 1; padding: 0 20px; }
.lb-row {
  display: flex; align-items: center;
  padding: 13px 0; border-bottom: 0.5px solid var(--border);
  gap: 14px;
}
.lb-row.first { background: #EDEAF3; margin: 0 -20px; padding: 13px 20px; }
.lb-rank { font-family: var(--mono); font-size: 13px; color: var(--muted); min-width: 32px; }
.lb-row.first .lb-rank { color: var(--blue); font-weight: 600; }
.lb-name { font-family: var(--serif); font-size: 24px; font-weight: 700; color: var(--ink); min-width: 90px; }
.lb-row.first .lb-name { font-style: italic; color: var(--blue); }
.lb-bar-wrap { flex: 1; height: 2px; background: var(--border); position: relative; }
.lb-bar { height: 2px; background: var(--ink); position: absolute; left: 0; top: 0; transition: width 1s ease 0.3s; }
.lb-row.first .lb-bar { background: var(--blue); }
.lb-score { font-family: var(--serif); font-size: 32px; font-weight: 900; color: var(--ink); line-height: 1; text-align: right; min-width: 50px; }
.lb-score-total { font-family: var(--cond); font-size: 12px; color: var(--muted); }
.rf-links { font-family: var(--cond); font-size: 11px; color: var(--muted); }
.rf-links span { cursor: pointer; transition: color 0.15s; }
.rf-links span:hover { color: var(--ink); }
.rf-actions { display: flex; align-items: center; gap: 14px; }

/* ── RESPONSIVE ── */
@media (max-width: 560px) {
  .filtres-cols { grid-template-columns: 1fr; gap: 16px; }
  .answers-grid { grid-template-columns: 1fr; }
  .accueil-body { flex-direction: column; }
  .accueil-right { width: 100%; border-left: none; border-top: 0.5px solid var(--border); padding: 16px 0 0; }
  .res-header { flex-direction: column; gap: 16px; }
  .global-stats { flex-wrap: wrap; gap: 16px; }
}

/* ══════════════════════════════════════════════════
   ÉCRAN EXPERT
══════════════════════════════════════════════════ */
.expert-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 8px;
}
.expert-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  cursor: pointer;
  border: 0.5px solid var(--border);
  background: transparent;
  text-align: left;
  width: 100%;
  transition: all 0.12s;
  position: relative;
}
.expert-card:hover { background: var(--surf); }
.expert-card.sel {
  background: var(--blue);
  border-color: var(--blue);
  color: white;
}
.expert-card.sel .fi-label { color: white; }
.expert-card.sel .fi-sub { color: rgba(255,255,255,0.65); }
.expert-card.sel .fi-check { border-color: white; background: white; }
.expert-card.sel .fi-check::after { opacity: 1; }
.expert-card.locked {
  opacity: 0.38;
  cursor: not-allowed;
}
.expert-card.locked:hover { background: transparent; }
.expert-lock {
  position: absolute;
  right: 12px; top: 50%;
  transform: translateY(-50%);
  font-size: 12px;
  color: var(--muted);
}
.expert-badge {
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.08em;
  background: var(--blue);
  color: white;
  padding: 2px 7px;
  margin-left: auto;
}
.expert-badge.coming {
  background: var(--border);
  color: var(--muted);
}
.expert-icon { font-size: 22px; flex-shrink: 0; }
.mode-switcher {
  display: flex;
  gap: 0;
  margin: 0 0 18px;
  border: 0.5px solid var(--border);
}
.mode-tab {
  flex: 1;
  padding: 9px 12px;
  font-family: var(--cond);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--muted);
  border-right: 0.5px solid var(--border);
  transition: all 0.12s;
}
.mode-tab:last-child { border-right: none; }
.mode-tab.active {
  background: var(--blue);
  color: white;
}
.mode-tab:hover:not(.active) { background: var(--surf); color: var(--ink); }
@media (max-width: 560px) {
  .expert-grid { grid-template-columns: 1fr; }
}
`;


