/* ═══════════════════════════════════════════════════════
   UTILITAIRES
═══════════════════════════════════════════════════════ */

/**
 * Logique de sélection : période et/ou thématique peuvent être null (= toutes)
 * - null / null      → pioche dans toutes les combinaisons
 * - periode / null   → toutes les thématiques de cette période
 * - null / thematique → toutes les périodes de cette thématique
 * - periode / thematique → pool ciblé
 *
 * nbNeeded : nombre exact de questions à tirer (TOTAL_TOURS × nbJoueurs).
 * Chaque question est unique dans la session — pas de répétition possible.
 * Si le pool est insuffisant, on répète en remélangant (cas extrêmement rare).
 */
function getQuestions(periode, thematique, nbNeeded) {
  let pool = [];

  const periodeIds    = periode    ? [periode]    : PERIODES.map(p => p.id);
  const thematiqueIds = thematique ? [thematique] : THEMATIQUES.map(t => t.id);

  periodeIds.forEach(pid => {
    thematiqueIds.forEach(tid => {
      const key = `${pid}-${tid}`;
      if (QUESTIONS[key]) pool = pool.concat(QUESTIONS[key]);
    });
  });

  // Mélange Fisher-Yates
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }

  // Si le pool contient moins de questions que nécessaire, on le duplique
  // (cas rare : filtre très précis + beaucoup de joueurs)
  while (pool.length < nbNeeded) {
    const extra = [...pool].sort(() => Math.random() - 0.5);
    pool = pool.concat(extra);
  }

  return pool.slice(0, nbNeeded);
}

function StyleTag() { return <style dangerouslySetInnerHTML={{ __html: STYLES }} />; }

/* Formatte la date/lieu à partir de l'index de question (si la question a ces champs)
   Les questions du pool original n'ont pas de champ year/place → on affiche Q n° */
function getQuestionMeta(q, idx, total) {
  if (q && q.year) {
    return { year: q.year, era: q.era || "", place: q.place || "" };
  }
  return { year: String(idx + 1).padStart(2, '0'), era: `/ ${total}`, place: "" };
}


